// R6b calibration: request-sum, cap 100, window 1m, one action (Bank Pay).

@id("pay_cap")
permit (
    principal,
    action == Bank::Action::"Pay",
    resource
)
when temporal {
    (sum a for (a: Long), (t: Timepoint). where (
        formerly within 1m (Bank::Action::"Pay"::request{ input.amount: a } && tp(t))
    )) <= 100
};

// R6b calibration: request-count, cap 3, window 1m, one action (Bank Pay).

@id("pay_cap")
permit (
    principal,
    action == Bank::Action::"Pay",
    resource
)
when temporal {
    (count for (t: Timepoint). where (
        formerly within 1m (Bank::Action::"Pay"::request && tp(t))
    )) <= 3
};

// R6b calibration: requests-minus-errors-count, cap 3, window 1m, one action (Bank Pay).

@id("pay_cap")
permit (
    principal,
    action == Bank::Action::"Pay",
    resource
)
when temporal {
    (count for (t: Timepoint). where (
        formerly within 1m (Bank::Action::"Pay"::request && tp(t))
    )) - (count for (t: Timepoint). where (
        formerly within 1m (Bank::Action::"Pay"::error && tp(t))
    )) <= 3
};
